"""`preview` = {file: (sheet, range)} for the page preview (build.py PREVIEW lists only the first five toolkits' files).
   Clinic & Pharmacy Admin toolkit: front desk, billing, pharmacy stock, lab samples, staff roster and equipment records.
   Admin and record-keeping only: no diagnosis, dosage or treatment content anywhere (owner rule for this kit)."""

PRIVACY = ('Patient details are private. Keep this file on your own computer or a drive only your clinic can open, put a password on it '
           '(File › Info › Protect Workbook › Encrypt with Password) and never post it in group chats. Follow the health-data rules that apply where you work.')
ADMIN_ONLY = 'This is an admin and record-keeping template. It holds no medical advice and does not replace your clinic\'s medical records or software.'

KITS = [
    dict(id='clinic', name='Clinic & Pharmacy Admin', icon='🏥', color='#E11D48',
         title='Clinic & Pharmacy Admin Toolkit: OPD Register, Medicine Expiry, Lab Register',
         desc='Free Excel OPD register with daily collection, patient billing register, pharmacy stock with batch expiry alerts, lab sample register, duty roster, equipment log and an OPD receipt maker.',
         intro=['A small clinic, nursing home, diagnostic collection centre or chemist shop runs on paperwork that has nothing to do with medicine: who came today and what they paid, which bills are still due, which medicine batches expire next month, which samples are still waiting for a report, who is on night duty and when the BP machine was last calibrated.',
                'This toolkit turns those front-office registers into Excel workbooks that total the day\'s collection, flag near-expiry stock and overdue reports, and print on A4. It holds no clinical content: it is for the reception desk, the pharmacy counter and the clinic manager. Patient data stays on your own computer.'],
         who='Doctors running their own clinic, clinic receptionists and managers, nursing homes, dental and eye clinics, physiotherapy centres, diagnostic collection centres and pharmacies.'),
]

