    dict(id='pharmacy-stock-expiry-excel', kit='clinic', kind='excel', icon='💊', name='Pharmacy Stock & Expiry Register (Excel)',
         title='Medicine Stock Register in Excel with Batch Number and Expiry Alert',
         desc='Free Excel pharmacy stock register: medicines by batch with expiry date, stock in and issued, balance, near-expiry and expired highlights, reorder flags and stock value.',
         files=[('Pharmacy-Stock-Expiry-Register.xlsx', 'Pharmacy stock and expiry workbook')],
         preview={'Pharmacy-Stock-Expiry-Register.xlsx': ('Batches', 'A3:N12')},
         lead='A batch-wise stock register for a clinic dispensary or chemist shop. Enter each purchase with its batch number and expiry date, record what is sold or issued from which batch, and the register shows the balance of every batch, colours batches that expire within your chosen number of days, marks expired stock in red and tells you which medicines have fallen to the reorder level.',
         inside=['Settings: "as on" date (today by default) and the near-expiry window in days (90 to start with)',
                 'Items sheet: medicine or product name, form, pack, rack or shelf, reorder level and the total balance of all its batches with a Reorder flag',
                 'Batches sheet: item, batch number, expiry date, supplier, invoice number, quantity received, purchase rate and MRP',
                 'Calculated for every batch: issued, balance, days to expiry, status (Expired, Near expiry, OK, Nil stock) and stock value',
                 'Issues sheet: date, item, batch (drop-down), quantity sold or issued, and bill or patient reference, 2,000 ready rows',
                 'Expiry summary: number of batches and stock value expired and expiring within 30, 60 and 90 days, to plan returns to suppliers'],
         steps=['On the Settings sheet leave the as-on date as =TODAY() and set how many days before expiry a batch should turn amber.',
                'List your medicines and products on the Items sheet with the reorder level for each.',
                'For every purchase, add a row on the Batches sheet: item, batch number, expiry date, supplier, invoice, quantity, purchase rate and MRP. Each batch gets its own row.',
                'When you sell or issue stock, add a row on the Issues sheet with the item, the batch it came from and the quantity.',
                'Open the Batches sheet and sort or filter by Status: amber batches are near expiry, red ones have expired. Sell the oldest batch first or return it to the supplier in time.',
                'The Items sheet shows the total balance of each medicine and flags the ones to reorder.'],
         tips=['Type the item name exactly as on the Items sheet (pick it from the drop-down) or its stock will not add up.',
               'Expiry printed as month and year (for example 03/2027) means the end of that month: type the last day of the month, 31-03-2027.',
               'Expired stock must be kept apart from saleable stock and handled as your local rules require. Mark the row "Returned" or "Destroyed" in the Remarks column once it leaves your shelf, and issue the quantity out.',
               PRIVACY,
               ADMIN_ONLY],
         faqs=[('Why record batch numbers at all?', 'Expiry dates belong to batches, not to the medicine name. Two strips of the same medicine bought a month apart can expire a year apart. Batch-wise stock is also what you need if a supplier or regulator recalls a batch.'),
               ('How is "near expiry" decided?', 'A batch with stock left is Near expiry when its expiry date is within the number of days set on the Settings sheet from the as-on date, and Expired when the date has passed. Batches with no stock left show Nil stock and are not coloured.'),
               ('Can I use it for surgical items and consumables?', 'Yes. Any item with a batch and expiry date works. For items without expiry, leave the expiry date empty; they show as OK.'),
               ('Does it tell me what dose to give?', 'No. This is a stock register only. It holds no dosage or prescribing information.')]),

